---------------------------------------------------------------- hide helpers (own attribute set Training_*)
local function hideOne(inst)
	if inst:GetAttribute("TrainingHidden") then return 0 end
	if inst:IsA("BasePart") then
		inst:SetAttribute("Training_T", inst.Transparency); inst:SetAttribute("Training_C", inst.CanCollide)
		inst:SetAttribute("Training_Q", inst.CanQuery); inst:SetAttribute("Training_Tc", inst.CanTouch)
		inst.Transparency = 1; inst.CanCollide = false; inst.CanQuery = false; inst.CanTouch = false
	elseif inst:IsA("Decal") or inst:IsA("Texture") then
		inst:SetAttribute("Training_T", inst.Transparency); inst.Transparency = 1
	elseif inst:IsA("Light") or inst:IsA("ParticleEmitter") or inst:IsA("Beam") or inst:IsA("SurfaceGui") or inst:IsA("BillboardGui") then
		inst:SetAttribute("Training_E", inst.Enabled); inst.Enabled = false
	else
		return 0
	end
	-- RoomFX switches RoomLight lights on by tag: untag hidden carriers (kept in an attribute for UNDO)
	if CS:HasTag(inst, "RoomLight") then CS:RemoveTag(inst, "RoomLight"); inst:SetAttribute("Training_Tags", "RoomLight") end
	inst:SetAttribute("TrainingHidden", true)
	return 1
end
local function unhideOne(inst)
	if not inst:GetAttribute("TrainingHidden") then return 0 end
	if inst:IsA("BasePart") then
		inst.Transparency = inst:GetAttribute("Training_T"); inst.CanCollide = inst:GetAttribute("Training_C")
		inst.CanQuery = inst:GetAttribute("Training_Q"); inst.CanTouch = inst:GetAttribute("Training_Tc")
	elseif inst:IsA("Decal") or inst:IsA("Texture") then
		inst.Transparency = inst:GetAttribute("Training_T")
	else
		inst.Enabled = inst:GetAttribute("Training_E")
	end
	local tags = inst:GetAttribute("Training_Tags")
	if tags then for _, t in string.split(tags, ",") do CS:AddTag(inst, t) end end
	for _, a in {"TrainingHidden", "Training_T", "Training_C", "Training_Q", "Training_Tc", "Training_E", "Training_Tags"} do inst:SetAttribute(a, nil) end
	return 1
end
local function hideTree(root) local n = hideOne(root); for _, d in root:GetDescendants() do n += hideOne(d) end; return n end

local function ensure(parent, name, class)
	local f = parent:FindFirstChild(name)
	if not f then f = Instance.new(class or "Folder"); f.Name = name; f.Parent = parent end
	return f
end
local rem = ensure(SS, "_RebuildRemoved")
local OLD_SPOTS, OLD_ARR = "Training_EnemySpots_Old", "Training_Arrivals_Old"

---------------------------------------------------------------- UNDO
if UNDO then
	local r2 = T:FindFirstChild("Range2"); if r2 then r2:Destroy(); say("Range2 removed") end
	local ex = T:FindFirstChild("Extras"); if ex then ex:Destroy(); say("Extras removed") end
	local off = SS:FindFirstChild("_TrainingExtrasOff"); if off then off:Destroy() end
	local n = 0
	for _, d in T:GetDescendants() do if d:GetAttribute("TrainingHidden") then n += unhideOne(d) end end
	say("unhidden", n)
	for _, pair in {{"EnemySpots", OLD_SPOTS}, {"Arrivals", OLD_ARR}} do
		local old = rem:FindFirstChild(pair[2])
		if old then
			local cur = T:FindFirstChild(pair[1]); if cur then cur:Destroy() end
			old.Name = pair[1]; old.Parent = T; say(pair[1], "restored", #old:GetChildren())
		end
	end
	local ta = T:FindFirstChild("TrainingArrive")
	if ta and ta:GetAttribute("Training_OrigCF") then ta.CFrame = ta:GetAttribute("Training_OrigCF"); ta:SetAttribute("Training_OrigCF", nil); say("TrainingArrive back", f3(ta.Position)) end
	say("UNDO done")
	return table.concat(log, "\n")
end

---------------------------------------------------------------- 1. hide the old Training geometry + old lights (restorable)
local hidden = 0
local arena = T:FindFirstChild("Arena")
if arena then hidden += hideTree(arena) end
for _, c in T:GetChildren() do if c.Name == "Light" and c:IsA("BasePart") then hidden += hideTree(c) end end
say("old Training hidden this run", hidden)

-- old Arrivals / EnemySpots out of the way (scripts read every child): moved once into ServerStorage._RebuildRemoved
for _, pair in {{"EnemySpots", OLD_SPOTS}, {"Arrivals", OLD_ARR}} do
	if not rem:FindFirstChild(pair[2]) then
		local cur = T:FindFirstChild(pair[1])
		if cur then cur.Name = pair[2]; cur.Parent = rem; say("old", pair[1], #cur:GetChildren(), "-> ServerStorage._RebuildRemoved." .. pair[2]) end
	end
end

