local ALLF = {F.Top, F.Bottom, F.Front, F.Back, F.Left, F.Right}
-- World-aligned grid (step 2): every face's tiles start on world multiples of the tile size, so the lines run on from box
-- to box. Texture origin per face measured in Studio (UV test cube): side faces V from the top edge downward; Top U along
-- -X from max X, V along -Z from max Z; Front (-Z) U from max X toward -X; Right (+X) U from max Z toward -Z; Back (+Z) U
-- from min X toward +X; Left (-X) U from min Z toward +Z. Boundaries sit at U = -offset (mod tile), hence offset = s * w0.
local function wmod(v, m) return v - m * math.floor(v / m) end
local function gridOffsets(p, face, spt)
	local c, h = p.Position, p.Size / 2
	local x0, x1, y1, z0, z1 = c.X - h.X, c.X + h.X, c.Y + h.Y, c.Z - h.Z, c.Z + h.Z
	if face == F.Top or face == F.Bottom then return wmod(-x1, spt), wmod(-z1, spt) end
	local v = wmod(-y1, spt)
	if face == F.Front then return wmod(-x1, spt), v
	elseif face == F.Back then return wmod(x0, spt), v
	elseif face == F.Right then return wmod(-z1, spt), v
	else return wmod(z0, spt), v end
end
local function grid(p, spt)
	spt = spt or GRID_SPT
	local aligned = p.ClassName == "Part" and p.CFrame.Rotation == CFrame.identity
	for _, f in ALLF do
		local ou, ov = 0, 0
		if aligned then ou, ov = gridOffsets(p, f, spt) end
		for k = 0, 1 do
			local t = Instance.new("Texture"); t.Name = "Grid"; t.Texture = GRID; t.Face = f
			t.StudsPerTileU = spt; t.StudsPerTileV = spt; t.Color3 = GRID_C; t.Transparency = GRID_T
			t.OffsetStudsU = ou + k * 0.06; t.OffsetStudsV = ov + k * 0.06; t.Parent = p
			nTex += 1
		end
	end
end
local function grime(p)
	for _, f in {F.Front, F.Back, F.Left, F.Right, F.Top} do
		local t = Instance.new("Texture"); t.Name = "Grime"; t.Texture = GRIME; t.Face = f
		t.StudsPerTileU = 4; t.StudsPerTileV = 4; t.Color3 = Color3.new(0, 0, 0); t.Transparency = 0.9; t.Parent = p
		nTex += 1
	end
end
local function mk(class, name, size, cf, colour, mat, variant, parent)
	local p = Instance.new(class); p.Name = name; p.Anchored = true; p.Size = size; p.CFrame = cf
	p.Color = colour; p.Material = mat; p.MaterialVariant = variant or ""; p.Reflectance = 0
	p.TopSurface = Enum.SurfaceType.Smooth; p.BottomSurface = Enum.SurfaceType.Smooth
	p.CanTouch = false; p.Parent = parent; nParts += 1
	return p
end
local function deco(p) -- non-colliding, never cover, never blocks a shot
	p.CanCollide = false; p.CanQuery = false; p.CanTouch = false; p:SetAttribute("NotCover", true)
end
local counts = {}
for _, it in LAYOUT do
	if it.kind == "pad" or it.kind == "bin" then continue end     -- extras: built from EXTRAS into Training.Extras (section 6)
	local k = KIND[it.kind]
	if not k then say("no kind", it.kind); continue end
	local folder = ensure(R, GROUP[it.kind])
	local sx, sz = it.x1 - it.x0, it.z1 - it.z0
	local cx, cz = (it.x0 + it.x1) / 2, (it.z0 + it.z1) / 2
	local yb = FLOOR + it.y0
	if it.kind == "bridge" then yb -= 0.04 end   -- lap1: bridge tops were coplanar (624.00) with the block tops they rest on
	local colour = k[1]
	if it.kind == "gfloor" then colour = GFLOOR_TONE[it.tone or 0] end
	if it.kind == "line" then colour = LINE_TONE[it.tone or "olive"] end
	local p
	if it.kind == "ramp" then
		-- WedgePart: high edge at local +Z. rise = side where the top meets the block
		local d = ({N = Vector3.zAxis, S = -Vector3.zAxis, E = Vector3.xAxis, W = -Vector3.xAxis})[it.rise]
		local len = (it.rise == "N" or it.rise == "S") and sz or sx
		local wid = (it.rise == "N" or it.rise == "S") and sx or sz
		local c = Vector3.new(cx, yb + it.h / 2, cz)
		p = mk("WedgePart", k[7], Vector3.new(wid, it.h, len), CFrame.lookAt(c, c - d), colour, k[2], k[3], folder)
		p:SetAttribute("To", it.to)
	elseif it.kind == "truss" then
		p = mk("TrussPart", k[7], Vector3.new(2, it.h, 2), CFrame.new(cx, yb + it.h / 2, cz), colour, k[2], k[3], folder)
		p:SetAttribute("To", it.to)
	else
		p = mk("Part", k[7], Vector3.new(sx, it.h, sz), CFrame.new(cx, yb + it.h / 2, cz), colour, k[2], k[3], folder)
	end
	p.CanCollide = k[5]; p.CanQuery = k[5]
	p.CastShadow = k[2] ~= M.Neon
	if k[6] then p:SetAttribute("NotCover", true) end
	if it.kind == "line" then deco(p) end
	if k[4] then grid(p, GRID_SPT_BIG[it.kind]) end
	if it.kind == "crate" then
		grime(p)
		-- dark steel straps round the crate (decor)
		for _, fy in {0.22, 0.78} do
			local s = mk("Part", "CrateStrap", Vector3.new(sx + 0.12, 0.35, sz + 0.12), CFrame.new(cx, yb + it.h * fy, cz), rgb(48, 48, 46), M.Metal, "TacMetal", folder)
			deco(s)
		end
	end
	if it.id then p:SetAttribute("Id", it.id) end
	if it.link then p:SetAttribute("Link", it.link) end
	-- olive datum bands (decor, 0.2 proud): bastions and towers get a band; towers two
	if it.kind == "bastion" or it.kind == "tower" then
		for _, by in (it.kind == "tower" and {12, 30} or {10}) do
			local b = mk("Part", "Band", Vector3.new(sx + 0.4, 2, sz + 0.4), CFrame.new(cx, yb + by + 1, cz), OLIVE_BAND, M.Concrete, "TacConcrete", folder)
			deco(b)
		end
	end
	counts[it.kind] = (counts[it.kind] or 0) + 1
	if nParts % 60 == 0 then task.wait() end
end
-- perimeter wall dressing on the inner faces: olive band 607..610 and a cream Neon line under it
local shell = ensure(R, "Shell")
for _, it in LAYOUT do
	if it.kind ~= "wall" then continue end
	local sx, sz = it.x1 - it.x0, it.z1 - it.z0
	local cx, cz = (it.x0 + it.x1) / 2, (it.z0 + it.z1) / 2
	local roomX = cx > 129.5 and 241 or 0          -- gallery walls face the gallery centre line
	local band, line
	if sx < sz then -- wall runs along z; inner face toward roomX
		local s = (roomX < cx) and -1 or 1
		local fx = cx + s * sx / 2
		band = mk("Part", "WallBand", Vector3.new(0.4, 3, sz), CFrame.new(fx + s * 0.2, FLOOR + 8.5, cz), OLIVE_BAND, M.Concrete, "TacConcrete", shell)
		line = mk("Part", "WallLine", Vector3.new(0.3, 0.25, sz), CFrame.new(fx + s * 0.15, FLOOR + 6.75, cz), LINE_TONE.cream, M.Neon, "", shell)
	else
		local s = (0 < cz) and -1 or 1
		local fz = cz + s * sz / 2
		band = mk("Part", "WallBand", Vector3.new(sx, 3, 0.4), CFrame.new(cx, FLOOR + 8.5, fz + s * 0.2), OLIVE_BAND, M.Concrete, "TacConcrete", shell)
		line = mk("Part", "WallLine", Vector3.new(sx, 0.25, 0.3), CFrame.new(cx, FLOOR + 6.75, fz + s * 0.15), LINE_TONE.cream, M.Neon, "", shell)
	end
	deco(band); deco(line); line.CastShadow = false
end
say("Range2 parts", nParts, "textures", nTex)
local cs = {}; for k, v in counts do table.insert(cs, k .. "=" .. v) end; table.sort(cs); say("pieces", table.concat(cs, " "))

---------------------------------------------------------------- 3. lights: Neon ceiling panels carrying PointLights, tagged like the old Training lights
local LF = ensure(R, "Lights")
for _, l in LIGHTS do
	local p = mk("Part", "Light", Vector3.new(6, 0.3, 6), CFrame.new(l.x, FLOOR + 48 - 0.15, l.z), rgb(236, 232, 218), M.Neon, "", LF)
	deco(p); p.CastShadow = false
	local pl = Instance.new("PointLight"); pl.Brightness = 1.2; pl.Range = 60; pl.Color = rgb(235, 232, 222); pl.Shadows = false; pl.Parent = p
	p:SetAttribute("Room", "Training"); CS:AddTag(p, "RoomLight")
end
say("lights", #LIGHTS, "(RoomLight, Room = Training; RoomFX radius 175 from (0,606,0) still to be widened for the corners + gallery)")

---------------------------------------------------------------- 4. signs (never block shots: CanCollide / CanQuery / CanTouch false, NotCover)
local SF = ensure(R, "Signs")
local function label(part, face, text, ppsd)
	local g = Instance.new("SurfaceGui"); g.Name = "Text"; g.Face = face; g.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
	g.PixelsPerStud = ppsd or 50; g.LightInfluence = 0; g.Brightness = 1.2; g.MaxDistance = 0; g.Parent = part
	local l = Instance.new("TextLabel"); l.Name = "Label"; l.BackgroundTransparency = 1; l.Size = UDim2.fromScale(1, 0.8)
	l.Position = UDim2.fromScale(0, 0.1); l.Text = text; l.TextScaled = true; l.TextColor3 = rgb(236, 232, 218)
	l.FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Heavy); l.Parent = g
end
for _, s in SIGNS do
	if s.kind == "hang" then
		local pos = Vector3.new(s.x, FLOOR + s.y, s.z)
		local p = mk("Part", "DistSign", Vector3.new(6, 3, 0.2), CFrame.lookAt(pos, pos - Vector3.xAxis), rgb(39, 40, 37), M.SmoothPlastic, "", SF)
		deco(p); p.CastShadow = false; label(p, F.Front, s.text, 40)
		local trim = mk("Part", "DistSignTrim", Vector3.new(6, 0.2, 0.25), CFrame.lookAt(pos + Vector3.new(0, 1.6, 0), pos + Vector3.new(-1, 1.6, 0)), LINE_TONE.olive, M.Neon, "", SF)
		deco(trim); trim.CastShadow = false
	elseif s.kind == "wall" then
		local pos = Vector3.new(s.x - 0.08 - 0.05, FLOOR + s.y, s.z)
		local p = mk("Part", "DistSign", Vector3.new(5, 2.6, 0.1), CFrame.lookAt(pos, pos - Vector3.xAxis), rgb(39, 40, 37), M.SmoothPlastic, "", SF)
		deco(p); p.CastShadow = false; label(p, F.Front, s.text, 40)
	elseif s.kind == "floor" then
		local p = mk("Part", "FloorStencil", Vector3.new(12, 0.05, 3), CFrame.new(s.x, FLOOR + 0.1 + 0.03, s.z), rgb(150, 148, 138), M.Concrete, "TacConcrete", SF)
		deco(p); p.Transparency = 1; p.CastShadow = false; label(p, F.Top, s.text, 40)
		p.Text.Label.TextColor3 = rgb(236, 232, 218); p.Text.LightInfluence = 1
	end
end
say("signs", #SIGNS)
R.Parent = T

---------------------------------------------------------------- 5. Arrivals (16) + TrainingArrive, EnemySpots (44; direct children only)
local function freshFolder(name)
	local f = T:FindFirstChild(name)
	if f then for _, c in f:GetChildren() do c:Destroy() end else f = Instance.new("Folder"); f.Name = name; f.Parent = T end
	return f
end
local function marker(name, size, cf, parent)
	local p = Instance.new("Part"); p.Name = name; p.Anchored = true; p.Size = size; p.CFrame = cf; p.Transparency = 1
	p.CanCollide = false; p.CanQuery = false; p.CanTouch = false; p.CastShadow = false; p.Parent = parent
	return p
end
local ARR_Y = FLOOR + 0.1 + 3.2      -- plaza top 600.1 + 3.2 (the old Arrive parts stood 3.2 above the 600 floor)
local af = freshFolder("Arrivals")
for _, a in ARRIVALS do
	local pos = Vector3.new(a.x, ARR_Y, a.z)
	local dir = Vector3.new(math.cos(math.rad(a.deg)), 0, math.sin(math.rad(a.deg)))
	marker("Arrive", Vector3.new(2, 1, 2), CFrame.lookAt(pos, pos + dir), af)
end
local ta = T:FindFirstChild("TrainingArrive")
if ta then
	if ta:GetAttribute("Training_OrigCF") == nil then ta:SetAttribute("Training_OrigCF", ta.CFrame) end
	local pos = Vector3.new(0, ARR_Y, 0); ta.CFrame = CFrame.lookAt(pos, pos + Vector3.xAxis)   -- plaza centre facing the gallery
end
local sf = freshFolder("EnemySpots")
local nGal = 0
for _, s in SPOTS do
	local pos = Vector3.new(s.x, FLOOR + s.roof + 3, s.z)
	local cf
	if s.gallery then cf = CFrame.lookAt(pos, pos - Vector3.xAxis)                       -- faces the firing line (x 136)
	else cf = CFrame.lookAt(pos, Vector3.new(0, pos.Y, 0)) end                           -- faces the spawn plaza
	local p = marker(s.gallery and "GallerySpot" or "Spot", Vector3.new(1, 1, 1), cf, sf)
	p:SetAttribute("Zone", s.zone)
	if s.gallery then
		nGal += 1
		p:SetAttribute("Gallery", true); p:SetAttribute("Distance", s.gallery.dist); p:SetAttribute("Lane", s.gallery.lane)
	end
end
say("Arrivals", #af:GetChildren(), "TrainingArrive", ta and f3(ta.Position), "EnemySpots", #sf:GetChildren(), "gallery (Gallery=true)", nGal)
---------------------------------------------------------------- 6. Training extras geometry (step 2): Training.Extras.<Feature>
-- Read by the step-2 scripts (notes/training_extras_done.md). A feature switched off in Shared.Config.TrainingConfig (or by the
-- ReplicatedStorage attribute TX_<Feature> = false) has its folder moved to ServerStorage._TrainingExtrasOff by
-- TrainingExtrasManager at server start, so it leaves nothing behind.
do
	local oldEx = T:FindFirstChild("Extras"); if oldEx then oldEx:Destroy() end
	local EX = Instance.new("Folder"); EX.Name = "Extras"
	local nEx = {}
	local function count(k) nEx[k] = (nEx[k] or 0) + 1 end
	-- jump pads: dark steel plate, olive Neon ring + chevrons; LandAt = world point on the landing surface
	local PF = ensure(EX, "JumpPads")
	for i, pd in EXTRAS.pads do
		local top = FLOOR + pd.y
		local land = Vector3.new(pd.lx, FLOOR + pd.ly, pd.lz)
		local c = Vector3.new(pd.x, top + 0.2, pd.z)
		local flat = Vector3.new(land.X, c.Y, land.Z)
		local cf = (flat - c).Magnitude > 0.1 and CFrame.lookAt(c, flat) or CFrame.new(c)
		local base = mk("Part", "JumpPad", Vector3.new(4, 0.4, 4), cf, rgb(48, 48, 46), M.Metal, "TacMetal", PF)
		base.CanCollide = true; base.CanQuery = true; base.CanTouch = false; base:SetAttribute("NotCover", true)
		base:SetAttribute("LandAt", land); base:SetAttribute("Apex", 6); base:SetAttribute("PadId", i)
		CS:AddTag(base, "TrainingJumpPad")
		for _, e in {{0, 1.75, 4, 0.5}, {0, -1.75, 4, 0.5}, {1.75, 0, 0.5, 3}, {-1.75, 0, 0.5, 3}} do      -- ring
			local r = mk("Part", "PadRing", Vector3.new(e[3], 0.06, e[4]), cf * CFrame.new(e[1], 0.22, e[2]), rgb(96, 108, 52), M.Neon, "", PF)
			deco(r); r.CastShadow = false
		end
		for _, z in {0.6, -0.4} do                                                                          -- chevrons toward the landing (-Z = look)
			for _, sgn in {-1, 1} do
				local a = mk("Part", "PadArrow", Vector3.new(1.3, 0.06, 0.3), cf * CFrame.new(sgn * 0.42, 0.22, z) * CFrame.Angles(0, sgn * math.rad(-40), 0), rgb(180, 177, 166), M.Neon, "", PF)
				deco(a); a.CastShadow = false
			end
		end
		count("pads")
	end
	-- tightropes: visual rope (non-colliding) + invisible 1.2-wide walk box flush with the end surfaces (NotCover)
	local TF = ensure(EX, "Tightropes")
	for _, rp in EXTRAS.ropes do
		local y = FLOOR + rp.y
		local a, b = Vector3.new(rp.x0, y, rp.z0), Vector3.new(rp.x1, y, rp.z1)
		local dir = (b - a).Unit
		local a2, b2 = a - dir, b + dir                                      -- 1 stud into each end surface: no gap at the edge
		local len, mid = (b2 - a2).Magnitude, (a2 + b2) / 2
		local down = Vector3.new(0, 0.2, 0)
		local walk = mk("Part", "RopeWalk", Vector3.new(1.2, 0.4, len), CFrame.lookAt(mid - down, b2 - down), rgb(120, 110, 90), M.Fabric, "", TF)
		walk.Transparency = 1; walk.CanCollide = true; walk.CanQuery = true; walk.CanTouch = false; walk.CastShadow = false
		walk:SetAttribute("NotCover", true)
		local vis = mk("Part", "Rope", Vector3.new(len, 0.45, 0.45), CFrame.lookAt(mid - down, b2 - down) * CFrame.Angles(0, math.rad(90), 0), rgb(200, 186, 150), M.Fabric, "", TF)
		vis.Shape = Enum.PartType.Cylinder; deco(vis)
		for _, e in {a, b} do                                                                                -- olive end posts
			for _, sd in {-1, 1} do
				local side = dir:Cross(Vector3.yAxis) * sd * 0.9
				local post = mk("Part", "RopePost", Vector3.new(0.3, 2.2, 0.3), CFrame.new(e + side + Vector3.new(0, 1.1, 0)), OLIVE_BAND, M.Metal, "", TF)
				deco(post)
			end
		end
		count("ropes")
	end
	-- weapon-swap bins: olive weapon crates with an F prompt (Training only: TrainingBinsController / TrainingBinsManager)
	local BF = ensure(EX, "SwapBins")
	for _, bn in EXTRAS.bins do
		local m = Instance.new("Model"); m.Name = "SwapBin"
		local y = FLOOR + bn.y
		local at = Vector3.new(bn.x, y + 1.25, bn.z)
		local face = Vector3.new(0, at.Y, 0) - at
		local cf = CFrame.lookAt(at, at + (face.Magnitude > 1 and face.Unit or Vector3.xAxis))
		local body = mk("Part", "Body", Vector3.new(3, 2.5, 3), cf, rgb(65, 94, 56), M.SmoothPlastic, "", m)
		body.CanCollide = true; body.CanQuery = true; grime(body)
		local lid = mk("Part", "Lid", Vector3.new(3.2, 0.35, 3.2), cf * CFrame.new(0, 1.42, 0), rgb(48, 48, 46), M.Metal, "TacMetal", m)
		lid.CanCollide = true; lid.CanQuery = true
		local stripe = mk("Part", "Stripe", Vector3.new(3.06, 0.3, 3.06), cf * CFrame.new(0, 0.55, 0), rgb(180, 177, 166), M.Neon, "", m)
		deco(stripe); stripe.CastShadow = false
		local att = Instance.new("Attachment"); att.Name = "PromptAt"; att.Position = Vector3.new(0, 1.6, 0); att.Parent = body
		local pr = Instance.new("ProximityPrompt"); pr.Name = "BinPrompt"; pr.ActionText = "Change Weapon"; pr.ObjectText = "Weapon Crate"
		pr.KeyboardKeyCode = Enum.KeyCode.F; pr.GamepadKeyCode = Enum.KeyCode.ButtonY; pr.HoldDuration = 0; pr.MaxActivationDistance = 8
		pr.RequiresLineOfSight = false; pr:SetAttribute("TrainingBin", true); pr.Parent = att
		m:SetAttribute("TrainingBin", true); m.PrimaryPart = body; m.Parent = BF
		count("bins")
	end
	-- DPS dummy spots (1-stud markers, surface + 3, facing the shooter) for TrainingDpsManager
	local DF = ensure(EX, "DpsDummies")
	for _, d in EXTRAS.dps do
		local pos = Vector3.new(d.x, FLOOR + 3, d.z)
		local cf = d.face == "-x" and CFrame.lookAt(pos, pos - Vector3.xAxis) or CFrame.lookAt(pos, Vector3.new(0, pos.Y, 0))
		local p = marker("DpsSpot", Vector3.new(1, 1, 1), cf, DF); p:SetAttribute("Zone", d.face == "-x" and "gallery" or "boulevard")
		count("dps")
	end
	-- floating 1-HP bullseyes: the Ball is the hit volume (CanQuery on: the first thing a shot meets wins, so no collaterals),
	-- the face is a camera-facing BillboardGui (Scale = studs, Scale-only UI rule). TrainingTargetsManager pops / respawns them.
	local BU = ensure(EX, "Bullseyes")
	local RINGS = {{1, rgb(196, 40, 40)}, {0.78, rgb(236, 232, 218)}, {0.56, rgb(196, 40, 40)}, {0.34, rgb(236, 232, 218)}, {0.14, rgb(196, 40, 40)}}
	for i, b in EXTRAS.bulls do
		local p = Instance.new("Part"); p.Name = "Bullseye"; p.Shape = Enum.PartType.Ball; p.Size = Vector3.new(3, 3, 3)
		p.Position = Vector3.new(b.x, FLOOR + b.y, b.z); p.Anchored = true; p.Transparency = 1; p.CanCollide = false; p.CanQuery = true
		p.CanTouch = false; p.CastShadow = false; p:SetAttribute("NotCover", true); CS:AddTag(p, "TrainingTarget")
		local g = Instance.new("BillboardGui"); g.Name = "Face"; g.Size = UDim2.fromScale(3, 3); g.LightInfluence = 0.25; g.MaxDistance = 400
		g.Parent = p
		for _, r in RINGS do
			local f = Instance.new("Frame"); f.AnchorPoint = Vector2.new(0.5, 0.5); f.Position = UDim2.fromScale(0.5, 0.5)
			f.Size = UDim2.fromScale(r[1], r[1]); f.BackgroundColor3 = r[2]; f.BorderSizePixel = 0; f.Parent = g
			local uc = Instance.new("UICorner"); uc.CornerRadius = UDim.new(0.5, 0); uc.Parent = f
		end
		p.Parent = BU
		count("bullseyes")
	end
	EX.Parent = T
	local cs2 = {}; for k, v in nEx do table.insert(cs2, k .. "=" .. v) end; table.sort(cs2); say("Extras", table.concat(cs2, " "))
end
return table.concat(log, "\n")
